#include <stdio.h>

#pragma comment(lib, "advapi32.lib")

static BOOL EnablePrivilege(LPCWSTR name) {
    HANDLE token = nullptr;
    if (!OpenProcessToken(GetCurrentProcess(),
            TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, &token)) {
        return FALSE;
    }

    LUID luid = {};
    BOOL enabled = LookupPrivilegeValueW(nullptr, name, &luid);
    if (enabled) {
        TOKEN_PRIVILEGES privileges = {};
        privileges.PrivilegeCount = 1;
        privileges.Privileges[0].Luid = luid;
        privileges.Privileges[0].Attributes = SE_PRIVILEGE_ENABLED;
        enabled = AdjustTokenPrivileges(token, FALSE, &privileges, 0,
            nullptr, nullptr);
        if (enabled && GetLastError() == ERROR_NOT_ALL_ASSIGNED) {
            enabled = FALSE;
        }
    }

    CloseHandle(token);
    return enabled;
}

int main() {
    EnablePrivilege(L"SeBackupPrivilege");
    EnablePrivilege(L"SeRestorePrivilege");

    const char* sourcePath = "Software\\NtExplorerExample";
    HKEY sourceKey = nullptr;
    if (RegCreateKeyExA(HKEY_CURRENT_USER, sourcePath, 0, nullptr, 0,
            KEY_ALL_ACCESS, nullptr, &sourceKey, nullptr) != ERROR_SUCCESS) {
        return 1;
    }
    RegSetValueExA(sourceKey, "Value", 0, REG_SZ,
        reinterpret_cast<const BYTE*>("test"), 5);

    char hiveFile[MAX_PATH] = {};
    GetTempPathA(MAX_PATH, hiveFile);
    strcat_s(hiveFile, "ntexplorer-load.hiv");
    DeleteFileA(hiveFile);

    LSTATUS status = RegSaveKeyA(sourceKey, hiveFile, nullptr);
    RegCloseKey(sourceKey);
    if (status != ERROR_SUCCESS) {
        printf("RegSaveKeyA failed: %ld\n", status);
        RegDeleteTreeA(HKEY_CURRENT_USER, sourcePath);
        return 1;
    }

    status = RegLoadKeyA(HKEY_LOCAL_MACHINE, "NtExplorerExample", hiveFile);
    printf("RegLoadKeyA: %ld\n", status);
    if (status == ERROR_SUCCESS) {
        RegUnLoadKeyA(HKEY_LOCAL_MACHINE, "NtExplorerExample");
    }

    DeleteFileA(hiveFile);
    RegDeleteTreeA(HKEY_CURRENT_USER, sourcePath);
    return 0;
}

