            READ_CONTROL | WRITE_DAC, &key) != ERROR_SUCCESS) {
        return 1;
    }

    DWORD size = 0;
    RegGetKeySecurity(key, DACL_SECURITY_INFORMATION, nullptr, &size);
    auto descriptor = static_cast<PSECURITY_DESCRIPTOR>(
        LocalAlloc(LPTR, size));
    if (descriptor != nullptr &&
        RegGetKeySecurity(key, DACL_SECURITY_INFORMATION, descriptor, &size)
            == ERROR_SUCCESS) {
        // Re-applying the current descriptor is a no-op demonstration.
        RegSetKeySecurity(key, DACL_SECURITY_INFORMATION, descriptor);
    }

    LocalFree(descriptor);
    RegCloseKey(key);
    return 0;
}

